SELECT model, count() as requests FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) AND model IN ({{ gf_str_multi('model') }}) GROUP BY model ORDER BY requests DESC LIMIT 20